1	/// Payment gateway abstraction.
2	///
3	/// `PaymentGateway` is a synchronous configuration trait — it describes the
4	/// identity and signature scheme of one payment provider.  All async I/O is
5	/// handled by the standalone functions in `signature.rs`, `import.rs`, and
6	/// `handlers.rs`; this keeps the trait `dyn`-safe and avoids the `async-trait`
7	/// dependency.
8	use sqlx::PgPool;
9	use uuid::Uuid;
10	
11	use super::models::GatewayConfigRow;
12	
13	// ============================================================
14	// Error type
15	// ============================================================
16	
17	#[derive(Debug, thiserror::Error)]
18	pub enum GatewayError {
19	    #[error("Gateway '{0}' not found or inactive")]
20	    NotFound(String),
21	
22	    #[error("Signature verification failed")]
23	    BadSignature,
24	
25	    #[error("Replay detected: nonce already used or timestamp too old")]
26	    Replay,
27	
28	    #[error("Callback payload malformed: {0}")]
29	    BadPayload(String),
30	
31	    #[error("Database error: {0}")]
32	    Db(#[from] sqlx::Error),
33	}
34	
35	impl From<GatewayError> for crate::error::AppError {
36	    fn from(e: GatewayError) -> Self {
37	        match e {
38	            GatewayError::NotFound(s)   => crate::error::AppError::BadRequest(s),
39	            GatewayError::BadSignature  => crate::error::AppError::Unauthorized(
40	                "Callback signature verification failed".to_string(),
41	            ),
42	            GatewayError::Replay        => crate::error::AppError::BadRequest(
43	                "Replay detected: nonce already used or timestamp too old".to_string(),
44	            ),
45	            GatewayError::BadPayload(s) => crate::error::AppError::BadRequest(s),
46	            GatewayError::Db(e)         => crate::error::AppError::Database(e),
47	        }
48	    }
49	}
50	
51	// ============================================================
52	// Trait
53	// ============================================================
54	
55	/// Configuration surface of an offline payment gateway provider.
56	///
57	/// Implementors describe how to extract anti-replay fields from an inbound
58	/// HTTP request and what HMAC algorithm the provider uses to sign payloads.
59	pub trait PaymentGateway: Send + Sync {
60	    /// Stable machine identifier, e.g. `"alipay"` or `"wechat_pay"`.
61	    fn name(&self) -> &str;
62	
63	    /// Raw HMAC shared secret (bytes).
64	    fn hmac_secret_bytes(&self) -> &[u8];
65	
66	    /// HMAC algorithm the provider uses (`"sha256"` | `"sha512"`).
67	    fn hmac_algorithm(&self) -> &str;
68	
69	    /// HTTP header name carrying the provider signature.
70	    fn sig_header(&self) -> &str;
71	
72	    /// HTTP header name carrying the nonce.
73	    fn nonce_header(&self) -> &str;
74	
75	    /// HTTP header name carrying the Unix timestamp (seconds).
76	    fn ts_header(&self) -> &str;
77	
78	    /// Whether the timestamp should be included in the signed string.
79	    fn ts_in_sig(&self) -> bool;
80	}
81	
82	// ============================================================
83	// DB-backed implementation
84	// ============================================================
85	
86	/// Payment gateway loaded from the `payments.gateway_configs` table.
87	#[derive(Debug, Clone)]
88	pub struct DbGateway {
89	    config: GatewayConfigRow,
90	}
91	
92	impl DbGateway {
93	    pub fn new(config: GatewayConfigRow) -> Self {
94	        DbGateway { config }
95	    }
96	}
97	
98	impl PaymentGateway for DbGateway {
99	    fn name(&self) -> &str { &self.config.name }
100	
101	    fn hmac_secret_bytes(&self) -> &[u8] { self.config.hmac_secret.as_bytes() }
102	
103	    fn hmac_algorithm(&self) -> &str { &self.config.hmac_algorithm }
104	
105	    fn sig_header(&self) -> &str { &self.config.sig_header }
106	
107	    fn nonce_header(&self) -> &str { &self.config.nonce_header }
108	
109	    fn ts_header(&self) -> &str { &self.config.ts_header }
110	
111	    fn ts_in_sig(&self) -> bool { self.config.ts_in_sig }
112	}
113	
114	// ============================================================
115	// In-memory test/offline implementation
116	// ============================================================
117	
118	/// An offline gateway for development and simulation.
119	/// Uses a well-known test secret that can be overridden via environment.
120	pub struct OfflineGateway {
121	    secret: String,
122	}
123	
124	impl OfflineGateway {
125	    pub fn new(secret: impl Into<String>) -> Self {
126	        OfflineGateway { secret: secret.into() }
127	    }
128	}
129	
130	impl PaymentGateway for OfflineGateway {
131	    fn name(&self)             -> &str  { "offline_test" }
132	    fn hmac_secret_bytes(&self) -> &[u8] { self.secret.as_bytes() }
133	    fn hmac_algorithm(&self)   -> &str  { "sha256" }
134	    fn sig_header(&self)       -> &str  { "X-Signature" }
135	    fn nonce_header(&self)     -> &str  { "X-Nonce" }
136	    fn ts_header(&self)        -> &str  { "X-Timestamp" }
137	    fn ts_in_sig(&self)        -> bool   { true }
138	}
139	
140	// ============================================================
141	// Loader
142	// ============================================================
143	
144	/// Load an active gateway configuration from the database by name.
145	pub async fn load_gateway(
146	    pool: &PgPool,
147	    name: &str,
148	) -> Result<DbGateway, GatewayError> {
149	    let row = sqlx::query_as!(
150	        GatewayConfigRow,
151	        r#"
152	        SELECT id, name, display_name, hmac_secret, hmac_algorithm,
153	               sig_header, nonce_header, ts_header, ts_in_sig,
154	               is_active, created_at, updated_at
155	        FROM payments.gateway_configs
156	        WHERE name = $1 AND is_active = TRUE
157	        "#,
158	        name,
159	    )
160	    .fetch_optional(pool)
161	    .await?
162	    .ok_or_else(|| GatewayError::NotFound(name.to_string()))?;
163	
164	    Ok(DbGateway::new(row))
165	}
166	
167	/// Load all active gateway configurations.
168	pub async fn list_gateways(pool: &PgPool) -> Result<Vec<GatewayConfigRow>, sqlx::Error> {
169	    sqlx::query_as!(
170	        GatewayConfigRow,
171	        r#"
172	        SELECT id, name, display_name, hmac_secret, hmac_algorithm,
173	               sig_header, nonce_header, ts_header, ts_in_sig,
174	               is_active, created_at, updated_at
175	        FROM payments.gateway_configs
176	        WHERE is_active = TRUE
177	        ORDER BY name
178	        "#,
179	    )
180	    .fetch_all(pool)
181	    .await
182	}
