1	//! Anti-replay and callback signature verification tests.
2	//!
3	//! All tests in this file exercise pure functions that require no database or
4	//! network access.  Integration scenarios requiring a live PostgreSQL connection
5	//! are documented as commented stubs at the bottom.
6	//!
7	//! Run: `cargo test --test replay_attack`
8	
9	use chrono::Utc;
10	use transitops_backend::payments::signature::{
11	    build_signed_string, hmac_sha256_hex, hmac_sha512_hex, sha256_hex,
12	    validate_timestamp, MAX_TIMESTAMP_SKEW_SECS, ReplayError,
13	};
14	
15	// ── Timestamp window ──────────────────────────────────────────────────────────
16	
17	#[test]
18	fn timestamp_skew_window_is_five_minutes() {
19	    assert_eq!(MAX_TIMESTAMP_SKEW_SECS, 300);
20	}
21	
22	#[test]
23	fn current_timestamp_accepted() {
24	    let now = Utc::now().timestamp();
25	    assert!(validate_timestamp(now).is_ok());
26	}
27	
28	#[test]
29	fn timestamp_at_positive_boundary_accepted() {
30	    let now = Utc::now().timestamp();
31	    assert!(validate_timestamp(now - MAX_TIMESTAMP_SKEW_SECS).is_ok());
32	}
33	
34	#[test]
35	fn timestamp_at_negative_boundary_accepted() {
36	    let now = Utc::now().timestamp();
37	    assert!(validate_timestamp(now + MAX_TIMESTAMP_SKEW_SECS).is_ok());
38	}
39	
40	#[test]
41	fn timestamp_one_second_past_stale_rejected() {
42	    let now = Utc::now().timestamp();
43	    let err = validate_timestamp(now - MAX_TIMESTAMP_SKEW_SECS - 1).unwrap_err();
44	    assert!(matches!(err, ReplayError::TimestampStale(_)));
45	}
46	
47	#[test]
48	fn timestamp_one_second_past_future_rejected() {
49	    let now = Utc::now().timestamp();
50	    let err = validate_timestamp(now + MAX_TIMESTAMP_SKEW_SECS + 1).unwrap_err();
51	    assert!(matches!(err, ReplayError::TimestampStale(_)));
52	}
53	
54	#[test]
55	fn stale_timestamp_error_carries_actual_delta() {
56	    let now = Utc::now().timestamp();
57	    let ts  = now - 10_000; // ~2.8 hours ago
58	    match validate_timestamp(ts).unwrap_err() {
59	        ReplayError::TimestampStale(delta) => {
60	            assert!(delta > MAX_TIMESTAMP_SKEW_SECS,
61	                "delta {} should exceed MAX_TIMESTAMP_SKEW_SECS {}", delta, MAX_TIMESTAMP_SKEW_SECS);
62	        }
63	        other => panic!("unexpected error: {:?}", other),
64	    }
65	}
66	
67	#[test]
68	fn unix_epoch_zero_rejected() {
69	    // A timestamp of 0 is always stale regardless of when tests run.
70	    let err = validate_timestamp(0).unwrap_err();
71	    assert!(matches!(err, ReplayError::TimestampStale(_)));
72	}
73	
74	// ── Signed-string construction ────────────────────────────────────────────────
75	
76	#[test]
77	fn signed_string_with_ts_has_three_dot_separated_parts() {
78	    let s = build_signed_string("nonce-abc", 1_700_000_000, b"payload", true);
79	    let parts: Vec<&str> = s.splitn(3, '.').collect();
80	    assert_eq!(parts.len(), 3, "expected nonce.timestamp.hash");
81	    assert_eq!(parts[0], "nonce-abc");
82	    assert_eq!(parts[1], "1700000000");
83	    assert_eq!(parts[2].len(), 64, "body hash should be 64 hex chars");
84	}
85	
86	#[test]
87	fn signed_string_without_ts_has_two_dot_separated_parts() {
88	    let s = build_signed_string("nonce-abc", 1_700_000_000, b"payload", false);
89	    let parts: Vec<&str> = s.splitn(3, '.').collect();
90	    assert_eq!(parts.len(), 2, "expected nonce.hash only");
91	    assert_eq!(parts[0], "nonce-abc");
92	    assert!(!s.contains("1700000000"), "timestamp must not appear in signed string");
93	}
94	
95	#[test]
96	fn body_change_changes_signed_string() {
97	    let s1 = build_signed_string("n", 100, b"original-body", true);
98	    let s2 = build_signed_string("n", 100, b"tampered!body", true);
99	    assert_ne!(s1, s2, "tampered body must produce different signed string");
100	}
101	
102	#[test]
103	fn nonce_change_changes_signed_string() {
104	    let s1 = build_signed_string("nonce-legit",   100, b"body", true);
105	    let s2 = build_signed_string("nonce-attacker", 100, b"body", true);
106	    assert_ne!(s1, s2);
107	}
108	
109	#[test]
110	fn timestamp_change_changes_signed_string_when_ts_in_sig() {
111	    let s1 = build_signed_string("n", 1_000, b"body", true);
112	    let s2 = build_signed_string("n", 2_000, b"body", true);
113	    assert_ne!(s1, s2);
114	}
115	
116	/// When `ts_in_sig = false`, a replayed message with a different timestamp but
117	/// same nonce+body produces the SAME signed string, so the nonce check alone
118	/// stops the replay.
119	#[test]
120	fn timestamp_irrelevant_when_ts_not_in_sig() {
121	    let s1 = build_signed_string("n", 1_000, b"body", false);
122	    let s2 = build_signed_string("n", 2_000, b"body", false);
123	    assert_eq!(s1, s2, "timestamp must not affect signed string when ts_in_sig=false");
124	}
125	
126	#[test]
127	fn single_byte_body_change_changes_hash() {
128	    // Flipping case of one character must produce a different signed string.
129	    let s1 = build_signed_string("n", 100, b"Amount=100.00", true);
130	    let s2 = build_signed_string("n", 100, b"Amount=100.01", true);
131	    assert_ne!(s1, s2);
132	}
133	
134	// ── HMAC-SHA256 ───────────────────────────────────────────────────────────────
135	
136	#[test]
137	fn hmac_sha256_is_deterministic() {
138	    let h1 = hmac_sha256_hex(b"key", b"message");
139	    let h2 = hmac_sha256_hex(b"key", b"message");
140	    assert_eq!(h1, h2);
141	}
142	
143	#[test]
144	fn hmac_sha256_output_is_64_lowercase_hex_chars() {
145	    let h = hmac_sha256_hex(b"key", b"message");
146	    assert_eq!(h.len(), 64);
147	    assert!(h.chars().all(|c| c.is_ascii_hexdigit() && !c.is_uppercase()),
148	        "HMAC output should be lower-case hex");
149	}
150	
151	#[test]
152	fn hmac_sha256_sensitive_to_key_change() {
153	    let h1 = hmac_sha256_hex(b"key-a", b"msg");
154	    let h2 = hmac_sha256_hex(b"key-b", b"msg");
155	    assert_ne!(h1, h2);
156	}
157	
158	#[test]
159	fn hmac_sha256_sensitive_to_message_change() {
160	    let h1 = hmac_sha256_hex(b"key", b"original");
161	    let h2 = hmac_sha256_hex(b"key", b"tampered");
162	    assert_ne!(h1, h2);
163	}
164	
165	#[test]
166	fn hmac_sha256_empty_message_does_not_panic() {
167	    let _ = hmac_sha256_hex(b"key", b"");
168	}
169	
170	// ── HMAC-SHA512 ───────────────────────────────────────────────────────────────
171	
172	#[test]
173	fn hmac_sha512_is_deterministic() {
174	    assert_eq!(
175	        hmac_sha512_hex(b"secret", b"msg"),
176	        hmac_sha512_hex(b"secret", b"msg"),
177	    );
178	}
179	
180	#[test]
181	fn hmac_sha512_output_is_128_lowercase_hex_chars() {
182	    let h = hmac_sha512_hex(b"key", b"message");
183	    assert_eq!(h.len(), 128);
184	    assert!(h.chars().all(|c| c.is_ascii_hexdigit() && !c.is_uppercase()));
185	}
186	
187	#[test]
188	fn hmac_sha256_and_sha512_produce_different_outputs() {
189	    // Same inputs → different digest lengths and different values.
190	    let h256 = hmac_sha256_hex(b"key", b"msg");
191	    let h512 = hmac_sha512_hex(b"key", b"msg");
192	    assert_ne!(h256, h512);
193	}
194	
195	// ── SHA-256 body hash ─────────────────────────────────────────────────────────
196	
197	#[test]
198	fn sha256_empty_body_is_well_known_constant() {
199	    // SHA-256("") = e3b0c44298fc1c149afbf4c8996fb924...
200	    let h = sha256_hex(b"");
201	    assert!(h.starts_with("e3b0c442"),
202	        "SHA-256 of empty bytes should start with e3b0c442, got {}", &h[..8]);
203	    assert_eq!(h.len(), 64);
204	}
205	
206	#[test]
207	fn sha256_is_deterministic() {
208	    let h1 = sha256_hex(b"test-payload");
209	    let h2 = sha256_hex(b"test-payload");
210	    assert_eq!(h1, h2);
211	}
212	
213	#[test]
214	fn sha256_case_sensitive() {
215	    // Capitalising one byte changes the hash.
216	    assert_ne!(sha256_hex(b"body"), sha256_hex(b"Body"));
217	}
218	
219	#[test]
220	fn sha256_output_is_64_hex_chars() {
221	    assert_eq!(sha256_hex(b"arbitrary input").len(), 64);
222	}
