1	//! Offline behaviour and channel adapter failure tests.
2	//!
3	//! Core invariant: inbox delivery MUST succeed even when all external channel
4	//! adapters are unavailable or return errors.  The bus is designed so that
5	//! external channel failures are non-fatal and never abort inbox delivery.
6	//!
7	//! Pure tests in this file verify adapter availability detection when no
8	//! connector URL is configured.  Full fan-out integration tests require a
9	//! database and are documented as stubs at the bottom.
10	//!
11	//! Run: `cargo test --test offline`
12	
13	use transitops_backend::notifications::adapters::{
14	    email::EmailAdapter,
15	    sms::SmsAdapter,
16	    wecom::WeComAdapter,
17	    AdapterRegistry, NotificationAdapter,
18	};
19	
20	// ── Adapter availability (no connector URL) ───────────────────────────────────
21	
22	/// Email adapter is inert when no relay URL is configured.
23	#[test]
24	fn email_adapter_unavailable_when_relay_url_is_none() {
25	    let adapter = EmailAdapter::new(None, "noreply@test.local".to_string());
26	    assert!(!adapter.is_available());
27	}
28	
29	/// SMS adapter is inert when no gateway URL is configured.
30	#[test]
31	fn sms_adapter_unavailable_when_gateway_url_is_none() {
32	    let adapter = SmsAdapter::new(None);
33	    assert!(!adapter.is_available());
34	}
35	
36	/// WeCom adapter is inert when no webhook URL is configured.
37	#[test]
38	fn wecom_adapter_unavailable_when_webhook_url_is_none() {
39	    let adapter = WeComAdapter::new(None);
40	    assert!(!adapter.is_available());
41	}
42	
43	// ── Adapter channel names ─────────────────────────────────────────────────────
44	
