1	//! Alert deduplication and severity escalation tests.
2	//!
3	//! Pure-logic tests cover: KPI anomaly severity thresholds, reconciliation
4	//! alert severity mapping, and the zero-discrepancy early-exit guard.
5	//!
6	//! Core alert idempotency (at most one open alert per entity+type) requires a
7	//! live database and is documented as integration stubs at the bottom.
8	//!
9	//! Run: `cargo test --test alert_dedup`
10	
11	use transitops_backend::alerting::detector::KPI_CHECK_INTERVAL_SECS;
12	
13	// ── Constants ─────────────────────────────────────────────────────────────────
14	
15	#[test]
16	fn kpi_check_interval_is_30_minutes() {
17	    assert_eq!(KPI_CHECK_INTERVAL_SECS, 30 * 60);
18	}
19	
20	// ── KPI anomaly severity threshold logic ─────────────────────────────────────
21	//
22	// From `detector::check_metric_anomaly`:
23	//   if deviation_pct <= threshold_pct  → no alert
24	//   if deviation_pct > threshold_pct * 2 → "critical"
25	//   otherwise                           → "warning"
26	//
27	// Default threshold: 25 %
28	
29	fn kpi_severity(deviation_pct: f64, threshold_pct: f64) -> &'static str {
30	    if deviation_pct > threshold_pct * 2.0 { "critical" } else { "warning" }
31	}
32	
33	#[test]
34	fn deviation_at_single_threshold_would_not_trigger_alert() {
35	    // The detector returns early when deviation <= threshold.
36	    let threshold = 25.0_f64;
37	    let deviation = 25.0_f64;
38	    let would_alert = deviation > threshold;
39	    assert!(!would_alert, "exactly at threshold should not alert");
40	}
41	
42	#[test]
43	fn deviation_just_above_threshold_is_warning() {
44	    assert_eq!(kpi_severity(25.1, 25.0), "warning");
45	}
46	
47	#[test]
48	fn deviation_at_double_threshold_is_warning() {
49	    // 50.0 is NOT > 50.0, so still warning (strict >)
50	    assert_eq!(kpi_severity(50.0, 25.0), "warning");
51	}
52	
53	#[test]
54	fn deviation_just_above_double_threshold_is_critical() {
55	    assert_eq!(kpi_severity(50.001, 25.0), "critical");
56	}
57	
58	#[test]
59	fn deviation_way_above_double_threshold_is_critical() {
60	    assert_eq!(kpi_severity(200.0, 25.0), "critical");
61	}
62	
63	#[test]
64	fn custom_40pct_threshold_warning_range() {
65	    // threshold=40%: warning for 41–80%, critical for >80%
66	    assert_eq!(kpi_severity(60.0, 40.0), "warning");
67	    assert_eq!(kpi_severity(80.0, 40.0), "warning"); // exactly 2× → NOT critical
68	}
69	
70	#[test]
71	fn custom_40pct_threshold_critical_range() {
72	    assert_eq!(kpi_severity(80.1, 40.0), "critical");
73	}
74	
75	#[test]
76	fn zero_baseline_would_skip_check() {
77	    // In the detector: if avg.abs() < 1e-9 { return Ok(()); }
78	    let avg: f64 = 1e-10;
79	    let skip = avg.abs() < 1e-9;
80	    assert!(skip, "near-zero baseline must be skipped to avoid division artifacts");
81	}
82	
83	// ── Reconciliation alert severity ────────────────────────────────────────────
84	//
85	// From `detector::check_reconciliation_run`:
86	//   severity = if is_high { "critical" } else { "warning" }
87	
88	fn recon_severity(is_high: bool) -> &'static str {
89	    if is_high { "critical" } else { "warning" }
90	}
91	
92	#[test]
93	fn recon_alert_warning_when_not_high() {
94	    assert_eq!(recon_severity(false), "warning");
95	}
96	
97	#[test]
98	fn recon_alert_critical_when_high() {
99	    assert_eq!(recon_severity(true), "critical");
100	}
101	
102	/// No alert at all when discrepancy_count == 0 (guarded by early return in
103	/// `check_reconciliation_run`).
104	#[test]
105	fn zero_discrepancy_count_produces_no_alert() {
106	    let discrepancy_count: usize = 0;
107	    let would_create_alert = discrepancy_count > 0;
108	    assert!(!would_create_alert);
109	}
110	
111	/// A non-zero count always creates an alert regardless of is_high.
112	#[test]
113	fn nonzero_discrepancy_count_produces_alert() {
114	    let discrepancy_count: usize = 1;
115	    assert!(discrepancy_count > 0);
116	}
