1	/// Main inbox panel — opens as a slide-in drawer from the notification badge.
2	///
3	/// Data flow inside this component
4	/// ─────────────────────────────────
5	///
6	///   [panel opens]              [filter changes]
7	///        │                           │
8	///        └──────────┬────────────────┘
9	///                   ▼
10	///           load_notifications()
11	///               │
12	///               ├─ GET /notifications?status={filter}
13	///               ├─ POST /notifications/receipt  ← promotes queued → delivered
14	///               │   (server side-effect: user is online, DND bypassed)
15	///               └─ GET /notifications/unread-count  ← refresh badge
16	///               │
17	///               └─► dispatch SetNotifications + SetCounts
18	///
19	///   [Acknowledge click]
20	///       ├─ dispatch Acknowledge(id)   ← optimistic UI update
21	///       └─ POST /notifications/{id}/read
22	///
23	///   [Dismiss click]
24	///       ├─ dispatch Dismiss(id)       ← optimistic UI update
25	///       └─ POST /notifications/{id}/dismiss
26	///
27	///   [Mark All Read click]
28	///       ├─ dispatch AcknowledgeAll    ← optimistic UI update
29	///       └─ POST /notifications/read-all
30	use uuid::Uuid;
31	use wasm_bindgen_futures::spawn_local;
32	use yew::prelude::*;
33	
34	use crate::{
35	    components::notification_card::NotificationCard,
36	    services::notification_service,
37	    store::notification_store::{NotificationAction, NotificationContext},
38	    types::notification::StatusFilter,
39	};
40	
41	// ── Component ─────────────────────────────────────────────────────────────────
42	
43	#[function_component(InboxPanel)]
44	pub fn inbox_panel() -> Html {
45	    let ctx = use_context::<NotificationContext>().expect("NotificationContext missing");
46	
47	    // ── Load notifications ───────────────────────────────────────────────────
48	
49	    // Reusable fetch closure — reads current filter from context state.
50	    let fetch = {
51	        let ctx = ctx.clone();
52	        Callback::from(move |_: ()| {
53	            let ctx = ctx.clone();
54	            spawn_local(async move {
55	                ctx.dispatch(NotificationAction::SetLoading(true));
56	
57	                let status = ctx.state.filter.as_query_param();
58	
59	                match notification_service::fetch_notifications(status, 50, 0).await {
60	                    Ok(notifications) => {
61	                        // ── Delivery receipt ──────────────────────────────
62	                        // Inform the server which notifications the user is
63	                        // currently viewing. This promotes any queued ones to
64	                        // 'delivered' so the user sees DND-held items when
65	                        // they actively open their inbox.
66	                        let ids: Vec<Uuid> = notifications.iter().map(|n| n.id).collect();
67	                        if !ids.is_empty() {
68	                            let _ = notification_service::send_receipt(ids).await;
69	                        }
70	
71	                        // Refresh badge counts after receipt promotion
72	                        if let Ok(counts) = notification_service::fetch_unread_count().await {
73	                            ctx.dispatch(NotificationAction::SetCounts {
74	                                unread: counts.unread,
75	                                queued: counts.queued,
76	                            });
77	                        }
78	
79	                        ctx.dispatch(NotificationAction::SetNotifications(notifications));
80	                    }

