///
/// Shows all config versions for available templates.  Supports:
///   - Loading / empty / error states
///   - Publish / unpublish / schedule actions (admin only)
///     → triggers ReauthPrompt when server returns 403
///   - Link to diff view and rollout manager
use uuid::Uuid;
use wasm_bindgen_futures::spawn_local;
use yew::prelude::*;

use crate::{
    components::reauth_prompt::ReauthPrompt,
    services::ops_service,
    types::ops::ConfigVersion,
};

// ── Page state ────────────────────────────────────────────────────────────────

#[derive(Clone, PartialEq)]
enum PageState {
    Loading,
    Loaded(Vec<ConfigVersion>),
    Error(String),
}

#[derive(Clone, PartialEq)]
enum ActionState {
    Idle,
    Confirming { action: PendingAction, version_id: Uuid, template_id: Uuid },
    ReauthRequired { action: PendingAction, version_id: Uuid, template_id: Uuid },
    Working,
    Done(String),
    Failed(String),
}

#[derive(Clone, PartialEq, Debug)]
enum PendingAction { Publish, Unpublish }

// ── Component ─────────────────────────────────────────────────────────────────

/// Hardcoded known template IDs for the common config areas.
/// In production these would be fetched from GET /ops/configs/templates.
const DEMO_TEMPLATE_ID: &str = "00000000-0000-0000-0000-000000000001";

#[function_component(ConfigListPage)]
pub fn config_list_page() -> Html {
    // For demo purposes, use a fixed template_id; in production fetch templates first.
    let template_id: Uuid = DEMO_TEMPLATE_ID.parse().unwrap_or(Uuid::nil());

    let page_state   = use_state(|| PageState::Loading);
    let action_state = use_state(|| ActionState::Idle);

    // ── Fetch versions on mount ──────────────────────────────────────────────
    {
        let ps  = page_state.clone();
        let tid = template_id;
        use_effect_with((), move |_| {
            spawn_local(async move {
                match ops_service::list_versions(tid).await {
                    Ok(data) => {
                        // The API returns a ListResponse wrapper
                        let versions: Vec<ConfigVersion> =
                            data.get("data")
                                .and_then(|v| serde_json::from_value(v.clone()).ok())
                                .unwrap_or_default();
                        ps.set(PageState::Loaded(versions));
                    }
                    Err(e) => ps.set(PageState::Error(e)),
                }
            });
            || ()
        });
    }

    // ── Action handlers ──────────────────────────────────────────────────────

    let do_publish = {
        let action_state = action_state.clone();
        let template_id  = template_id;
        Callback::from(move |version_id: Uuid| {
            let ast = action_state.clone();
            let tid = template_id;
            spawn_local(async move {
                ast.set(ActionState::Working);
                match ops_service::publish_version(tid, version_id).await {
                    Ok(_)  => ast.set(ActionState::Done("Version published".to_string())),
                    Err(e) => {
                        if e.contains("[403]") {
                            ast.set(ActionState::ReauthRequired {
                                action: PendingAction::Publish,
                                version_id,
                                template_id: tid,
                            });
                        } else {
                            ast.set(ActionState::Failed(e));
                        }
                    }
                }
            });
        })
    };

    let do_unpublish = {
        let action_state = action_state.clone();
        let template_id  = template_id;
        Callback::from(move |version_id: Uuid| {
            let ast = action_state.clone();
            let tid = template_id;
            spawn_local(async move {
                ast.set(ActionState::Working);
                match ops_service::unpublish_version(tid, version_id).await {
                    Ok(_)  => ast.set(ActionState::Done("Version unpublished".to_string())),
                    Err(e) => {
                        if e.contains("[403]") {
                            ast.set(ActionState::ReauthRequired {
                                action: PendingAction::Unpublish,
                                version_id,
                                template_id: tid,
                            });
                        } else {
                            ast.set(ActionState::Failed(e));
                        }
                    }
                }
            });
        })
    };

    // ── Render ───────────────────────────────────────────────────────────────

    let content = match &*page_state {
        PageState::Loading => html! {
            <div class="loading-state">
                <div class="spinner" />
                <p>{ "Loading config versions…" }</p>
            </div>
        },
        PageState::Error(e) => html! {
            <div class="error-state">
                <p class="error-state__message">{ format!("Error loading versions: {}", e) }</p>
                <p>{ "Check your connection and try refreshing." }</p>
            </div>
        },
        PageState::Loaded(versions) if versions.is_empty() => html! {
            <div class="empty-state">
                <p class="empty-state__message">{ "No config versions found." }</p>
                <p>{ "Create a draft version to get started." }</p>
                <button class="btn btn--primary">{ "Create Draft" }</button>
            </div>
        },
        PageState::Loaded(versions) => {
            let pub_cb   = do_publish.clone();
            let unpub_cb = do_unpublish.clone();
            html! {
                <table class="data-table">
                    <thead>
                        <tr>
                            <th>{ "Version" }</th>
                            <th>{ "Status" }</th>
                            <th>{ "Published At" }</th>
                            <th>{ "Effective From" }</th>
                            <th>{ "Actions" }</th>
                        </tr>
                    </thead>
                    <tbody>
                        { for versions.iter().map(|v| {
                            let vid      = v.id;
                            let is_draft = v.is_draft();
                            let is_pub   = v.is_published();
                            let pub_cb2  = pub_cb.clone();
                            let upub_cb2 = unpub_cb.clone();
                            html! {
                                <tr key={vid.to_string()}>
                                    <td>{ format!("v{}", v.version_number) }</td>
                                    <td>
                                        <span class={format!("badge badge--{}", v.status)}>
                                            { v.status_label() }
                                        </span>
                                    </td>
                                    <td>
                                        { v.published_at.map(|t| t.format("%Y-%m-%d %H:%M UTC").to_string())
                                           .unwrap_or_else(|| "—".to_string()) }
                                    </td>
                                    <td>
                                        { v.effective_from.map(|t| t.format("%Y-%m-%d").to_string())
                                           .unwrap_or_else(|| "—".to_string()) }
                                    </td>
                                    <td class="action-cell">
                                        if is_draft {
                                            <button class="btn btn--small btn--primary"
                                                    onclick={Callback::from(move |_| pub_cb2.emit(vid))}>
                                                { "Publish" }
                                            </button>
                                        }
                                        if is_pub {
                                            <button class="btn btn--small btn--danger"
                                                    onclick={Callback::from(move |_| upub_cb2.emit(vid))}>
                                                { "Unpublish" }
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        }) }
                    </tbody>
                </table>
            }
        }
    };

    // ── Action feedback ───────────────────────────────────────────────────────

    let feedback = match &*action_state {
        ActionState::Working => html! {
            <div class="action-feedback action-feedback--working">{ "Working…" }</div>
        },
        ActionState::Done(msg) => html! {
            <div class="action-feedback action-feedback--success">{ msg }</div>
        },
        ActionState::Failed(e) => html! {
            <div class="action-feedback action-feedback--error">{ e }</div>
        },
        _ => html! {}
    };

    // ── Reauth prompt overlay ─────────────────────────────────────────────────

    let reauth_overlay = if let ActionState::ReauthRequired { action, version_id, template_id } = &*action_state {
        let action      = action.clone();
        let vid         = *version_id;
        let tid         = *template_id;
        let ast         = action_state.clone();
        let pub_cb_re   = do_publish.clone();
        let unpub_cb_re = do_unpublish.clone();

        html! {
            <ReauthPrompt
                on_success={Callback::from(move |_| {
                    // Retry the original action after successful reauth
                    match action {
                        PendingAction::Publish   => pub_cb_re.emit(vid),
                        PendingAction::Unpublish => unpub_cb_re.emit(vid),
                    }
                })}
                on_cancel={Callback::from(move |_| ast.set(ActionState::Idle))}
            />
        }
    } else {
        html! {}
    };

    html! {
        <div class="page">
            <header class="page__header">
                <h1 class="page__title">{ "Config Versions" }</h1>
                <div class="page__actions">
                    <button class="btn btn--primary">{ "+ New Draft" }</button>
                </div>
            </header>

            { feedback }

            <div class="page__body">
                { content }
            </div>

            { reauth_overlay }
        </div>
    }
}
"}

