                    Ok(_)  => ast.set(ActionState::Done("Stage activated".to_string())),
                    Err(e) => {
                        if e.contains("[403]") {
                            ast.set(ActionState::ReauthRequired {
                                stage_id, plan_id: pid, template_id: tid,
                            });
                        } else {
                            ast.set(ActionState::Failed(e));
                        }
                    }
                }
            });
        })
    };

    let body = match &*page_state {
        PageState::Empty => html! {
            <div class="empty-state">
                <p>{ "Enter a template ID and plan ID above to load a rollout plan." }</p>
                <p class="hint">
                    { "Rollout plans are created from a published config version. \
                       A plan progresses through stages: 10% → 50% → 100% of depots." }
                </p>
            </div>
        },
        PageState::Loading => html! { <div class="spinner" /> },
        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
        PageState::Loaded(plan) => {
            let act_cb = activate_stage.clone();
            html! {
                <div class="rollout-plan">
                    <div class="rollout-plan__meta">
                        <span>{ format!("Plan: {}", plan.id) }</span>
                        <span class={format!("badge badge--{}", plan.status)}>{ &plan.status }</span>
                        <span>{ format!("{}/{} depots", plan.current_stage, plan.total_depots) }</span>
                    </div>
                    <div class="rollout-stages">
                        { for plan.stages.iter().map(|stage| {
                            let sid    = stage.id;
                            let act_cb = act_cb.clone();
                            let is_pending = stage.status == "pending";
                            html! {
                                <div class="rollout-stage" key={sid.to_string()}>
                                    <div class="rollout-stage__header">
                                        <span class="rollout-stage__number">
                                            { format!("Stage {}", stage.stage_number) }
                                        </span>
                                        <span class="rollout-stage__pct">
                                            { format!("{}%", stage.target_percentage) }
                                        </span>
                                        <span class={format!("badge badge--{}", stage.status)}>
                                            { &stage.status }
                                        </span>
                                    </div>
                                    <div class="rollout-stage__detail">
                                        <span>{ format!("{} depots", stage.depot_count) }</span>
                                        if let Some(at) = stage.activated_at {
                                            <span>{ format!("Activated {}", at.format("%Y-%m-%d %H:%M")) }</span>
                                        }
                                    </div>
                                    if is_pending {
                                        <button class="btn btn--primary btn--small"
                                                onclick={Callback::from(move |_| act_cb.emit(sid))}>
                                            { "Activate Stage" }
                                        </button>
                                    }
                                </div>
                            }
                        }) }
                    </div>
                </div>
            }
        }
    };

    let reauth_overlay = if let ActionState::ReauthRequired { stage_id, plan_id: _, template_id: _ } = &*action_state {
        let sid = *stage_id;
        let ast = action_state.clone();
        let act = activate_stage.clone();
        html! {
            <ReauthPrompt
                on_success={Callback::from(move |_| act.emit(sid))}
                on_cancel={Callback::from(move |_| ast.set(ActionState::Idle))}
            />
        }
    } else { html! {} };

    let feedback = match &*action_state {
        ActionState::Working     => html! { <div class="action-feedback action-feedback--working">{ "Activating…" }</div> },
        ActionState::Done(msg)   => html! { <div class="action-feedback action-feedback--success">{ msg }</div> },
        ActionState::Failed(e)   => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
        _ => html! {}
    };

    html! {
        <div class="page">
            <header class="page__header">
                <h1 class="page__title">{ "Rollout Manager" }</h1>
            </header>
            <div class="page__body">
                <form onsubmit={on_load} class="inline-form">
                    <label class="form-field form-field--inline">
                        <span>{ "Template ID" }</span>
                        <input type="text" placeholder="uuid"
                               oninput={{let t = template_input.clone(); Callback::from(move |e: InputEvent| {
                                   let i: web_sys::HtmlInputElement = e.target_unchecked_into();
                                   t.set(i.value());
                               })}} class="form-field__input" />
                    </label>
                    <label class="form-field form-field--inline">
                        <span>{ "Plan ID" }</span>
                        <input type="text" placeholder="uuid"
                               oninput={{let p = plan_input.clone(); Callback::from(move |e: InputEvent| {
                                   let i: web_sys::HtmlInputElement = e.target_unchecked_into();
                                   p.set(i.value());
                               })}} class="form-field__input" />
                    </label>
                    <button type="submit" class="btn btn--secondary">{ "Load Plan" }</button>
                </form>
                { feedback }
                { body }
            </div>
            { reauth_overlay }
        </div>
    }
}
"}

