use yew::prelude::*;

use crate::{
    services::ops_service,
    types::ops::Trip,
};

#[derive(Clone, PartialEq)]
enum PageState { Loading, Loaded(Vec<Trip>), Error(String) }

#[derive(Clone, PartialEq)]
enum ActionState { Idle, Working, Done(String), Failed(String) }

#[function_component(TripsPage)]
pub fn trips_page() -> Html {
    let page_state   = use_state(|| PageState::Loading);
    let action_state = use_state(|| ActionState::Idle);

    {
        let ps = page_state.clone();
        use_effect_with((), move |_| {
            spawn_local(async move {
                match ops_service::list_trips().await {
                    Ok(trips) => ps.set(PageState::Loaded(trips)),
                    Err(e)    => ps.set(PageState::Error(e)),
                }
            });
            || ()
        });
    }

    let adjust_trip = {
        let ast = action_state.clone();
        Callback::from(move |trip_id: uuid::Uuid| {
            let ast = ast.clone();
            spawn_local(async move {
                ast.set(ActionState::Working);
                match ops_service::adjust_trip(trip_id, None, None).await {
                    Ok(_)  => ast.set(ActionState::Done("Trip updated".to_string())),
                    Err(e) => ast.set(ActionState::Failed(e)),
                }
            });
        })
    };

    let content = match &*page_state {
        PageState::Loading => html! { <div class="loading-state"><div class="spinner"/><p>{ "Loading trips…" }</p></div> },
        PageState::Error(e) => html! { <div class="error-state"><p class="error-state__message">{ e }</p></div> },
        PageState::Loaded(trips) if trips.is_empty() => html! {
            <div class="empty-state"><p>{ "No active trips." }</p></div>
        },
        PageState::Loaded(trips) => {
            let adj = adjust_trip.clone();
            html! {
                <table class="data-table">
                    <thead>
                        <tr>
                            <th>{ "Trip ID" }</th>
                            <th>{ "Route" }</th>
                            <th>{ "Departure" }</th>
                            <th>{ "Arrival" }</th>
                            <th>{ "Status" }</th>
                            <th>{ "Actions" }</th>
                        </tr>
                    </thead>
                    <tbody>
                        { for trips.iter().map(|t| {
                            let tid  = t.id;
                            let adj2 = adj.clone();
                            html! {
                                <tr key={tid.to_string()}>
                                    <td class="mono">{ &t.id.to_string()[..8] }{ "…" }</td>
                                    <td>{ &t.route_id.to_string()[..8] }{ "…" }</td>
                                    <td>{ t.departure_time.format("%H:%M").to_string() }</td>
                                    <td>{ t.arrival_time.format("%H:%M").to_string() }</td>
                                    <td>
                                        <span class={format!("badge badge--{}", t.status)}>{ &t.status }</span>
                                    </td>
                                    <td class="action-cell">
                                        if t.status == "scheduled" {
                                            <button class="btn btn--small btn--secondary"
                                                    onclick={Callback::from(move |_| adj2.emit(tid))}>
                                                { "Adjust" }
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        }) }
                    </tbody>
                </table>
            }
        }
    };

    let feedback = match &*action_state {
        ActionState::Working    => html! { <div class="action-feedback action-feedback--working">{ "Updating…" }</div> },
        ActionState::Done(msg)  => html! { <div class="action-feedback action-feedback--success">{ msg }</div> },
        ActionState::Failed(e)  => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
        ActionState::Idle       => html! {},
    };

    html! {
        <div class="page">
            <header class="page__header">
                <h1 class="page__title">{ "Trip Adjustments" }</h1>
            </header>
            { feedback }
            <div class="page__body">{ content }</div>
        </div>
    }
}
"}

