1	use chrono::{DateTime, Utc};
2	use serde::{Deserialize, Serialize};
3	use uuid::Uuid;
4	
5	// ── Core notification type (mirrors backend DeliveryResponse) ─────────────────
6	
7	#[derive(Clone, PartialEq, Deserialize)]
8	pub struct Notification {
9	    pub id:               Uuid,
10	    pub event_id:         Uuid,
11	    pub event_type:       String,
12	    pub severity:         String,
13	    pub source_entity_id: Option<Uuid>,
14	    pub payload:          serde_json::Value,
15	    pub status:           String,
16	    pub delivered_at:     Option<DateTime<Utc>>,
17	    pub read_at:          Option<DateTime<Utc>>,
18	    pub created_at:       DateTime<Utc>,
19	}
20	
21	impl Notification {
22	    // ── Status helpers ────────────────────────────────────────────────────────
23	
24	    pub fn is_unread(&self) -> bool { self.status == "delivered" }
25	    pub fn is_queued(&self) -> bool { self.status == "queued" }
26	    pub fn is_read(&self)   -> bool { self.status == "read" }
27	
28	    // ── Display helpers ───────────────────────────────────────────────────────
29	
30	    /// Extract a human-readable title from the payload, falling back to the
31	    /// event type formatted with word separators.
32	    pub fn title(&self) -> String {
33	        if let Some(t) = self.payload.get("title").and_then(|v| v.as_str()) {
34	            return t.to_string();
35	        }
36	        // e.g. "ops.trip.conflict_detected" → "ops › trip › conflict detected"
37	        self.event_type
38	            .replace('.', " › ")
39	            .replace('_', " ")
40	    }
41	
42	    /// Short summary text for the notification card body.
43	    pub fn message(&self) -> Option<String> {
44	        // Try explicit message field first (announcements, rule alerts)
45	        if let Some(m) = self.payload.get("message").and_then(|v| v.as_str()) {
46	            return Some(m.to_string());
47	        }
48	        // Fall back to description
49	        self.payload.get("description").and_then(|v| v.as_str()).map(String::from)
50	    }
51	
52	    /// CSS class suffix for severity colouring (use with `notification--{class}`).
53	    pub fn severity_class(&self) -> &str {
54	        match self.severity.as_str() {
55	            "critical" => "critical",
56	            "warning"  => "warning",
57	            _          => "info",
58	        }
59	    }
60	
61	    /// Unicode indicator shown beside the severity label.
62	    pub fn severity_icon(&self) -> &str {
63	        match self.severity.as_str() {
64	            "critical" => "🔴",
65	            "warning"  => "🟡",
66	            _          => "🔵",
67	        }
68	    }
69	
70	    /// Category prefix used to group notifications visually.
71	    pub fn category(&self) -> &str {
72	        if self.event_type.starts_with("ops.trip") {
73	            "Trip"
74	        } else if self.event_type.starts_with("ops.request") {
75	            "Request"
76	        } else if self.event_type.starts_with("sys") {
77	            "System"
78	        } else {
79	            "Other"
80	        }
81	    }
82	
83	    pub fn formatted_created_at(&self) -> String {
84	        self.created_at.format("%b %d, %H:%M UTC").to_string()
85	    }
86	
87	    pub fn formatted_delivered_at(&self) -> Option<String> {
88	        self.delivered_at
89	            .map(|t| t.format("%b %d, %H:%M UTC").to_string())
90	    }
91	
92	    pub fn formatted_read_at(&self) -> Option<String> {
93	        self.read_at.map(|t| t.format("%b %d, %H:%M UTC").to_string())
94	    }
95	}
96	
97	// ── API response types ────────────────────────────────────────────────────────
98	
99	#[derive(Clone, PartialEq, Deserialize, Default)]
100	pub struct UnreadCountResponse {
101	    pub unread: i64,
102	    pub queued: i64,
103	}
104	
105	// ── API request types ─────────────────────────────────────────────────────────
106	
107	/// Sent to POST /notifications/receipt when the inbox renders a batch.
108	#[derive(Serialize)]
109	pub struct ReceiptRequest {
110	    pub delivery_ids: Vec<Uuid>,
111	}
112	
113	// ── UI filter state ───────────────────────────────────────────────────────────
114	
115	#[derive(Clone, PartialEq, Default, Debug)]
116	pub enum StatusFilter {
117	    #[default]
118	    Unread,   // shows status='delivered' (unread)
119	    Queued,   // shows status='queued'   (held during DND)
120	    All,      // shows everything
121	}
122	
123	impl StatusFilter {
124	    pub fn as_query_param(&self) -> &'static str {
125	        match self {
126	            StatusFilter::Unread  => "unread",
127	            StatusFilter::Queued  => "queued",
128	            StatusFilter::All     => "all",
129	        }
130	    }
131	
132	    pub fn label(&self) -> &'static str {
133	        match self {
134	            StatusFilter::Unread  => "Unread",
135	            StatusFilter::Queued  => "Queued (DND held)",
136	            StatusFilter::All     => "All",
137	        }
138	    }
139	}
140

1	/// HTTP client layer for the notification API.
2	///
3	/// All functions are async and return `Result<T, gloo_net::Error>`.
4	/// The auth token is read from `localStorage["auth_token"]` and sent as a
5	/// Bearer header on every request. Callers handle errors via the store reducer.
6	use gloo_net::http::Request;
7	use uuid::Uuid;
8	use web_sys::window;
9	
10	use crate::types::notification::{Notification, ReceiptRequest, UnreadCountResponse};
11	
12	const BASE: &str = "/notifications";
13	
14	// ── Auth header helper ────────────────────────────────────────────────────────
15	
16	fn bearer() -> Option<String> {
17	    window()
18	        .and_then(|w| w.local_storage().ok()?)
19	        .and_then(|s| s.get_item("auth_token").ok()?)
20	        .map(|t| format!("Bearer {}", t))
21	}
22	
23	fn get(url: &str) -> Request {
24	    let req = Request::get(url);
25	    match bearer() {
26	        Some(h) => req.header("Authorization", &h),
27	        None    => req,
28	    }
29	}
30	
31	fn post(url: &str) -> Request {
32	    let req = Request::post(url);
33	    match bearer() {
34	        Some(h) => req.header("Authorization", &h),
35	        None    => req,
36	    }
37	}
38	
39	fn delete_req(url: &str) -> Request {
40	    let req = Request::delete(url);
41	    match bearer() {
42	        Some(h) => req.header("Authorization", &h),
43	        None    => req,
44	    }
45	}
46	
47	// ── Inbox ─────────────────────────────────────────────────────────────────────
48	
49	/// Fetch a paginated list of the caller's notifications.
50	/// `status` maps to the query param: `"unread"` | `"queued"` | `"read"` | `"all"`.
51	pub async fn fetch_notifications(
52	    status: &str,
53	    limit:  i64,
54	    offset: i64,
55	) -> Result<Vec<Notification>, gloo_net::Error> {
56	    get(&format!(
57	        "{}?status={}&limit={}&offset={}",
58	        BASE, status, limit, offset
59	    ))
60	    .send()
61	    .await?
62	    .json::<Vec<Notification>>()
63	    .await
64	}
65	
66	/// Lightweight poll for badge counters. Returns `{unread, queued}`.
67	pub async fn fetch_unread_count() -> Result<UnreadCountResponse, gloo_net::Error> {
68	    get(&format!("{}/unread-count", BASE))
69	        .send()
70	        .await?
71	        .json::<UnreadCountResponse>()
72	        .await
73	}
74	
75	/// Fetch the full details of a single notification (for the detail drawer).
76	pub async fn fetch_one(id: Uuid) -> Result<Notification, gloo_net::Error> {
77	    get(&format!("{}/{}", BASE, id))
78	        .send()
79	        .await?
80	        .json::<Notification>()
81	        .await
82	}
83	
84	// ── Acknowledge / Close ───────────────────────────────────────────────────────
85	
86	/// Acknowledge one notification — transitions `delivered` → `read`.
87	/// Sets `read_at` server-side (the read receipt timestamp).
88	pub async fn acknowledge(id: Uuid) -> Result<(), gloo_net::Error> {
89	    post(&format!("{}/{}/read", BASE, id))
90	        .send()
91	        .await?;
92	    Ok(())
93	}
94	
95	/// Acknowledge (mark read) all currently unread notifications in one call.
96	pub async fn acknowledge_all() -> Result<(), gloo_net::Error> {
97	    post(&format!("{}/read-all", BASE))
98	        .send()
99	        .await?;
100	    Ok(())
101	}
102	
103	/// Close/dismiss one notification — hides it from the default inbox view.
104	/// `dismissed` items are still queryable via `?status=all`.
105	pub async fn dismiss(id: Uuid) -> Result<(), gloo_net::Error> {
106	    post(&format!("{}/{}/dismiss", BASE, id))
107	        .send()
108	        .await?;
109	    Ok(())
110	}
111	
112	// ── Delivery receipts ─────────────────────────────────────────────────────────
113	
114	/// Send a delivery receipt for a batch of notification IDs.
115	///
116	/// Called by the inbox component immediately after rendering a page of results.
117	/// The backend promotes any `queued` deliveries in the list to `delivered`,
118	/// ensuring the user sees DND-held notifications when they actively open
119	/// their inbox.
120	///
121	/// Returns the number of queued items promoted on the server.
122	pub async fn send_receipt(ids: Vec<Uuid>) -> Result<u64, gloo_net::Error> {
123	    #[derive(serde::Deserialize)]
124	    struct Resp { promoted: u64 }
125	
126	    let body = ReceiptRequest { delivery_ids: ids };
127	    let resp = post(&format!("{}/receipt", BASE))
128	        .json(&body)
129	        .map_err(|e| gloo_net::Error::JsError(e.into()))?
130	        .send()
131	        .await?
132	        .json::<Resp>()
133	        .await?;
134	
135	    Ok(resp.promoted)
136	}
