                    match &pending {
                        PendingAction::Delete(id)  => del_cb.emit(*id),
                        PendingAction::Trigger(id) => trig_cb.emit(*id),
                        PendingAction::Create       => {
                            // Re-trigger form submit is not straightforward; just reset
                            ast.set(ActionState::Idle);
                        }
                    }
                })}
                on_cancel={Callback::from({
                    let ast = action_state.clone();
                    move |_| ast.set(ActionState::Idle)
                })}
            />
        }
    } else { html! {} };

    html! {
        <div class="page">
            <header class="page__header">
                <h1 class="page__title">{ "Report Schedules" }</h1>
            </header>
            <div class="page__body">
                <form onsubmit={create_schedule} class="inline-form">
                    <label class="form-field form-field--inline">
                        <span>{ "Metric ID" }</span>
                        <input type="text" placeholder="uuid"
                               oninput={{
                                   let m = metric_input.clone();
                                   Callback::from(move |e: InputEvent| {
                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
                                       m.set(el.value());
                                   })
                               }}
                               class="form-field__input" />
                    </label>
                    <label class="form-field form-field--inline">
                        <span>{ "Cron" }</span>
                        <input type="text" placeholder="0 8 * * 1"
                               value={(*cron_input).clone()}
                               oninput={{
                                   let c = cron_input.clone();
                                   Callback::from(move |e: InputEvent| {
                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
                                       c.set(el.value());
                                   })
                               }}
                               class="form-field__input" />
                    </label>
                    <button type="submit" class="btn btn--primary">{ "Schedule" }</button>
                </form>
                { feedback }
                { content }
            </div>
            { reauth_overlay }
        </div>
    }
}
