///
/// `Route` is the single source of truth for all navigable paths in the
/// backoffice SPA.  Each variant maps to one page component; role-gated
/// variants are wrapped in `RoleGuard` inside `switch()`.
pub mod alerting;
pub mod dispatcher;
pub mod finance;
pub mod notifications;
pub mod ops;
pub mod reporting;

mod login;
pub use login::LoginPage;

use yew::prelude::*;
use yew_router::prelude::*;

use crate::{
    components::{
        nav::NavSidebar,
        role_guard::{AuthGuard, RoleGuard},
    },
    types::auth::SessionInfo,
};

use alerting::alerts::AlertsPage;
use dispatcher::{conflicts::ConflictsPage, trips::TripsPage};
use finance::{
    reconciliation::ReconciliationPage,
    refunds::RefundsPage,
    statements::StatementsPage,
};
use notifications::{
    inbox::InboxPage,
    preferences::PreferencesPage,
    subscriptions::SubscriptionsPage,
};
use ops::{
    config_diff::ConfigDiffPage,
    config_list::ConfigListPage,
    rollout::RolloutManagerPage,
};
use reporting::{metrics::MetricsPage, schedules::SchedulesPage};

// ── Route enum ────────────────────────────────────────────────────────────────

#[derive(Clone, Routable, PartialEq)]
pub enum Route {
    // Auth
    #[at("/login")]
    Login,

    // Operations
    #[at("/ops/config")]
    ConfigList,
    #[at("/ops/diff")]
    ConfigDiff,
    #[at("/ops/rollout")]
    RolloutManager,

    // Dispatcher
    #[at("/dispatch/trips")]
    Trips,
    #[at("/dispatch/conflicts")]
    Conflicts,

    // Finance
    #[at("/finance/statements")]
    Statements,
    #[at("/finance/reconciliation")]
    Reconciliation,
    #[at("/finance/refunds")]
    Refunds,

    // Notifications (all roles)
    #[at("/notifications")]
    Inbox,
    #[at("/notifications/subscriptions")]
    Subscriptions,
    #[at("/notifications/preferences")]
    Preferences,

    // Reporting
    #[at("/reporting/metrics")]
    Metrics,
    #[at("/reporting/schedules")]
    ReportSchedules,

    // Alerting
    #[at("/alerts")]
    Alerts,

    // Default redirect
    #[not_found]
