3	/// Session information returned by GET /auth/session and POST /auth/login.
4	#[derive(Clone, PartialEq, Deserialize, Default, Debug)]
5	pub struct SessionInfo {
6	    pub username:   String,
7	    pub role:       String,
8	    pub session_id: Option<String>,
9	}
10	
11	impl SessionInfo {
12	    pub fn is_admin(&self) -> bool      { self.role == "operations_admin" }
13	    pub fn is_dispatcher(&self) -> bool { self.role == "dispatcher" }
14	    pub fn is_finance(&self) -> bool    { self.role == "finance_analyst" }
15	    pub fn is_staff(&self) -> bool      { self.role == "staff_user" }
16	
17	    /// Returns true for roles that can access the ops config area.
18	    pub fn can_ops_config(&self) -> bool {
19	        matches!(self.role.as_str(), "operations_admin" | "dispatcher" | "finance_analyst" | "staff_user")
20	    }
21	    /// Returns true for roles that can publish configs (admin only).
22	    pub fn can_publish(&self) -> bool { self.is_admin() }
23	    /// Returns true for roles that can access finance/reconciliation.
24	    pub fn can_finance(&self) -> bool { self.is_admin() || self.is_finance() }
25	    /// Returns true for roles that can access reporting.
26	    pub fn can_reporting(&self) -> bool {
27	        matches!(self.role.as_str(), "operations_admin" | "dispatcher" | "finance_analyst" | "staff_user")
28	    }
29	    /// Returns true for roles that can manage metrics (create/update/delete).
30	    pub fn can_manage_metrics(&self) -> bool { self.is_admin() || self.is_finance() }
31	    /// Returns true for roles that can view alerts.
32	    pub fn can_alerts(&self) -> bool {
33	        matches!(self.role.as_str(), "operations_admin" | "dispatcher" | "finance_analyst")
34	    }
35	}
