1	/// Authentication / session state store.
2	///
3	/// Persists the session token to `localStorage` so the user stays logged in
4	/// across page refreshes (offline-first: token is cached locally).
5	///
6	/// The `AuthContext` wraps (SessionInfo, token, dispatch) and is available to
7	/// any component in the tree via `use_context::<AuthContext>()`.
8	use std::rc::Rc;
9	
10	use web_sys::window;
11	use yew::prelude::*;
12	
13	use crate::types::auth::SessionInfo;
14	
15	const TOKEN_KEY: &str = "transitops_token";
16	
17	// ── State ─────────────────────────────────────────────────────────────────────
18	
19	#[derive(Clone, PartialEq, Debug, Default)]
20	pub struct AuthState {
21	    pub token:   Option<String>,
22	    pub session: Option<SessionInfo>,
23	    pub loading: bool,
24	}
25	
26	impl AuthState {
27	    pub fn is_authenticated(&self) -> bool {
28	        self.token.is_some() && self.session.is_some()
29	    }
30	
31	    pub fn role(&self) -> &str {
32	        self.session.as_ref().map(|s| s.role.as_str()).unwrap_or("")
33	    }
34	}
35	
36	// ── Actions ───────────────────────────────────────────────────────────────────
37	
38	pub enum AuthAction {
39	    SetToken(String),
40	    SetSession(SessionInfo),
41	    SetLoading(bool),
42	    Logout,
43	}
44	
45	// ── Reducer ───────────────────────────────────────────────────────────────────
46	
47	impl Reducible for AuthState {
48	    type Action = AuthAction;
49	
50	    fn reduce(self: Rc<Self>, action: Self::Action) -> Rc<Self> {
51	        match action {
52	            AuthAction::SetToken(token) => {
53	                // Persist to localStorage for offline-first usage
54	                if let Some(storage) = window().and_then(|w| w.local_storage().ok()).flatten() {
55	                    let _ = storage.set_item(TOKEN_KEY, &token);
56	                }
57	                Rc::new(AuthState {
58	                    token:   Some(token),
59	                    session: self.session.clone(),
60	                    loading: self.loading,
61	                })
62	            }
63	            AuthAction::SetSession(session) => Rc::new(AuthState {
64	                token:   self.token.clone(),
65	                session: Some(session),
66	                loading: self.loading,
67	            }),
68	            AuthAction::SetLoading(loading) => Rc::new(AuthState {
69	                loading,
70	                ..(*self).clone()
71	            }),
72	            AuthAction::Logout => {
73	                if let Some(storage) = window().and_then(|w| w.local_storage().ok()).flatten() {
74	                    let _ = storage.remove_item(TOKEN_KEY);
75	                }
76	                Rc::new(AuthState::default())
77	            }
78	        }
79	    }
80	}
81	
82	// ── Context type ──────────────────────────────────────────────────────────────
83	
84	pub type AuthContext = UseReducerHandle<AuthState>;
85	
86	// ── Load persisted token from localStorage ────────────────────────────────────
87	
88	pub fn load_persisted_token() -> Option<String> {
89	    window()
90	        .and_then(|w| w.local_storage().ok())
91	        .flatten()
92	        .and_then(|s| s.get_item(TOKEN_KEY).ok())
93	        .flatten()
94	}
95	
96	// ── Provider ──────────────────────────────────────────────────────────────────
97	
98	#[derive(Properties, PartialEq)]
99	pub struct AuthProviderProps {
100	    pub children: Children,
101	}
102	
103	/// Wraps the application tree and provides `AuthContext` to all descendants.
104	#[function_component(AuthProvider)]
105	pub fn auth_provider(props: &AuthProviderProps) -> Html {
106	    let state = use_reducer(AuthState::default);
107	
108	    // Restore token from localStorage on first render
109	    {
110	        let state = state.clone();
111	        use_effect_with((), move |_| {
112	            if let Some(token) = load_persisted_token() {
113	                state.dispatch(AuthAction::SetToken(token));
114	            }
115	            || ()
116	        });
117	    }
118	
119	    html! {
120	        <ContextProvider<AuthContext> context={state}>
121	            { for props.children.iter() }
122	        </ContextProvider<AuthContext>>
123	    }
124	}
125

