17	/// Root application component.
18	///
19	/// Provides the three context layers required by all descendant components:
20	///   1. `AuthProvider`         — session token + role (persisted to localStorage)
21	///   2. `InboxContextProvider` — unread notification badge state
22	///   3. `BrowserRouter`        — yew-router client-side routing
23	///
24	/// The shell renders `NavSidebar` (role-aware) alongside the current route's
25	/// page component; the sidebar is hidden on the `/login` route.
26	#[function_component(App)]
27	fn app() -> Html {
28	    html! {
29	        <AuthProvider>
30	            <InboxContextProvider>
31	                <BrowserRouter>
32	                    <AppShell />
33	                </BrowserRouter>
34	            </InboxContextProvider>
35	        </AuthProvider>
36	    }
37	}
38	
39	/// Inner shell that has access to the router context.
40	///
41	/// Shows the sidebar navigation for all routes except `/login` and `/404`.
42	#[function_component(AppShell)]
43	fn app_shell() -> Html {
44	    let route = use_route::<Route>();
45	    let show_nav = !matches!(route, Some(Route::Login) | Some(Route::NotFound) | None);
46	
47	    html! {
48	        <div class="app-layout">
49	            if show_nav {
50	                <NavSidebar />
51	            }
52	            <main class={if show_nav { "app-layout__content" } else { "app-layout__content app-layout__content--full" }}>
53	                <Switch<Route> render={switch} />
54	            </main>
55	        </div>
56	    }
57	}
